<script lang="ts">
 import {t} from '#lib/i18n.ts';
 import {onMount,onDestroy} from 'svelte';import Icon from './Icon.svelte';import {aromaChoices} from '#lib/content.ts';import {api,session,refreshSession,noteKey} from '#lib/client.svelte.ts';
 let {room,wine,hint,onEdit}:{room:string;wine:string;hint:string;onEdit?:()=>void}=$props();
 let form=$state({text:'',aromas:[] as string[],rating:0,sweetness:0,acidity:0});let status=$state('');let ready=$state(false);let timer:ReturnType<typeof setTimeout>;let revision=0;let savedRevision=0;let saving=false;let destroyed=false;
 function backup(){try{localStorage.setItem(noteKey(room,wine),JSON.stringify({owner:session.draftOwner,data:$state.snapshot(form),updated:Date.now(),pending:true}));}catch{}}
 async function save(){if(!ready||saving||savedRevision===revision)return;saving=true;const savingRevision=revision;const snapshot=$state.snapshot(form);status='Wird gespeichert …';try{await api('rooms/'+room+'/notes',{wine,data:snapshot});savedRevision=savingRevision;status='Gespeichert';if(savingRevision===revision){try{localStorage.setItem(noteKey(room,wine),JSON.stringify({owner:session.draftOwner,data:snapshot,updated:Date.now(),pending:false}));}catch{}}await refreshSession();}catch(e){status='Auf diesem Gerät gesichert. Server nicht erreichbar.';}saving=false;if(savedRevision!==revision){if(destroyed)keepalive();else timer=setTimeout(save,2500);}}
 function changed(){if(!ready)return;onEdit?.();revision++;backup();status='Auf diesem Gerät gesichert';clearTimeout(timer);timer=setTimeout(save,650);}
 function aroma(a:string){form.aromas=form.aromas.includes(a)?form.aromas.filter(x=>x!==a):[...form.aromas,a];changed();}
 function online(){save();}
 function keepalive(){fetch('/api/rooms/'+room+'/notes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({wine,data:$state.snapshot(form)}),keepalive:true}).catch(()=>{});}
 onMount(async()=>{if(!session.loaded)await refreshSession();if(destroyed)return;const existing=session.notes.find(n=>n.room===room&&n.wine===wine);if(existing)form={...form,...existing.data};try{const local=JSON.parse(localStorage.getItem(noteKey(room,wine))||'null');if(local?.pending&&local.owner===session.draftOwner&&(!existing||local.updated>new Date(existing.updated_at).getTime())){form={...form,...local.data};revision=1;status='Dein letzter Entwurf ist wieder da.';}}catch{}ready=true;if(revision)save();window.addEventListener('online',online);});
 onDestroy(()=>{destroyed=true;clearTimeout(timer);if(typeof window!=='undefined'){window.removeEventListener('online',online);if(savedRevision!==revision){backup();if(!saving)keepalive();}}});
</script>
<form class="note-form" aria-busy={!ready} onsubmit={(e)=>{e.preventDefault();save();}}><fieldset class="note-fields" aria-label="Deine Tasting Notes" disabled={!ready}>
 <p>{hint} {t('m_8c0cfe4922')}</p>
 <div><span class="field-heading">{t('m_71a871c6d8')}<small>{t('m_103167e885')}</small></span><div class="rating-buttons" role="group" aria-label={t('m_4b07f34152')}>{#each [1,2,3,4,5] as rating}<button type="button" class:selected={form.rating>=rating} aria-label={rating+' von 5 Sternen'} aria-pressed={form.rating===rating} onclick={()=>{form.rating=form.rating===rating?0:rating;changed();}}><Icon name="star" size={23}/></button>{/each}</div></div>
 <div><span class="field-heading">{t('m_22f8ead030')}<small>{t('m_0794742dc4')}</small></span><div class="aroma-options">{#each aromaChoices as a}<button type="button" class:selected={form.aromas.includes(a)} aria-pressed={form.aromas.includes(a)} onclick={()=>aroma(a)}>{a}{#if form.aromas.includes(a)} <span aria-hidden="true">✓</span>{/if}</button>{/each}</div></div>
 <label>{t('m_fc15b01dce')}<textarea bind:value={form.text} oninput={changed} rows="4" maxlength="6000" placeholder={t('m_864876a9c8')}></textarea></label>
 <div class="form-grid"><div><label for={'sweet-'+wine}>{t('m_4d850fca5f')}</label><input id={'sweet-'+wine} type="range" min="0" max="5" bind:value={form.sweetness} oninput={changed} aria-valuetext={form.sweetness===0?'Noch nicht eingeschätzt':form.sweetness+' von 5'}/><div class="range-labels"><span>{t('m_3d131180b6')}</span><span>{t('m_747287ef57')}</span></div></div><div><label for={'acid-'+wine}>{t('m_7f5c273874')}</label><input id={'acid-'+wine} type="range" min="0" max="5" bind:value={form.acidity} oninput={changed} aria-valuetext={form.acidity===0?'Noch nicht eingeschätzt':form.acidity+' von 5'}/><div class="range-labels"><span>{t('m_e98e330b35')}</span><span>{t('m_0ae82d177d')}</span></div></div></div>
 <div class="save-status" aria-live="polite"><Icon name={status==='Gespeichert'?'check':'notes'} size={13}/>{status||(ready?'Deine Eingaben werden automatisch gespeichert.':'Deine Notizen werden geladen …')}</div>
 {#if status.includes('Server nicht')}<button class="button outline" type="submit">{t('m_9568d7aa34')}</button>{/if}
</fieldset></form>
